{
  "name": "@assistant-ui/vue",
  "version": "0.0.5",
  "description": "Vue bindings for assistant-ui",
  "keywords": [
    "assistant",
    "ai",
    "chat",
    "vue",
    "nuxt"
  ],
  "author": "AgentbaseAI Inc.",
  "license": "MIT",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "files": [
    "dist",
    "src",
    "README.md"
  ],
  "sideEffects": false,
  "scripts": {
    "build": "aui-build",
    "test": "vitest run",
    "test:coverage": "vitest run --coverage --coverage.reporter=text --coverage.reporter=html --coverage.reporter=json-summary",
    "typecheck": "tsc --noEmit",
    "test:watch": "vitest"
  },
  "dependencies": {
    "@assistant-ui/core": "^0.3.30",
    "@assistant-ui/store": "^0.3.22",
    "@assistant-ui/tap": "^0.9.24"
  },
  "peerDependencies": {
    "@types/react": "*",
    "vue": "^3.5.0"
  },
  "devDependencies": {
    "@assistant-ui/x-buildutils": "workspace:*",
    "@types/node": "^26.6.5",
    "@types/react": "^19.3.0",
    "assistant-cloud": "workspace:*",
    "jsdom": "^30.1.3",
    "vitest": "^5.0.5",
    "vue": "^3.5.44"
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "homepage": "https://www.assistant-ui.com/",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/assistant-ui/assistant-ui.git",
    "directory": "packages/vue"
  },
  "bugs": {
    "url": "https://github.com/assistant-ui/assistant-ui/issues"
  }
}

